package com.rootrecord.minecraft.rootavacore;

import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;

import java.util.Collections;
import java.util.List;
import java.util.Locale;

public final class AvaCommand implements CommandExecutor, TabCompleter {

    private final RootAvaCorePlugin plugin;

    public AvaCommand(RootAvaCorePlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length > 0 && "reload".equalsIgnoreCase(args[0])) {
            if (!sender.hasPermission("rootavacore.admin")) {
                sender.sendMessage(plugin.colorize(plugin.config().noPermission()));
                return true;
            }
            plugin.reloadAll();
            sender.sendMessage(plugin.colorize(plugin.config().reloaded()));
            return true;
        }

        if (!sender.hasPermission("rootavacore.use")) {
            sender.sendMessage(plugin.colorize(plugin.config().noPermission()));
            return true;
        }
        if (!plugin.config().enabled()) {
            sender.sendMessage(plugin.colorize(plugin.config().disabled()));
            return true;
        }

        int online = Bukkit.getOnlinePlayers().size();
        String tpsText = formatTps();
        String line = plugin.config().statusLine()
                .replace("{version}", plugin.getDescription().getVersion())
                .replace("{online}", String.valueOf(online))
                .replace("{tps}", tpsText);
        sender.sendMessage(plugin.colorize(plugin.config().prefix() + line));
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        if (args.length == 1 && sender.hasPermission("rootavacore.admin")) {
            String partial = args[0].toLowerCase(Locale.ROOT);
            if ("reload".startsWith(partial)) {
                return List.of("reload");
            }
        }
        return Collections.emptyList();
    }

    private static String formatTps() {
        try {
            double[] tps = Bukkit.getTPS();
            if (tps != null && tps.length > 0) {
                double v = Math.min(20.0, tps[0]);
                return String.format(Locale.US, "%.1f", v);
            }
        } catch (Throwable ignored) {
            // Soft signal only — TPS may be unavailable on non-Paper forks.
        }
        return "n/a";
    }
}

package com.rootrecord.minecraft.rootavacore;

import com.rootrecord.minecraft.common.RootRecordFolders;
import com.rootrecord.minecraft.common.command.PluginCommandRegistrar;
import com.rootrecord.minecraft.common.config.RootRecordYamlConfig;
import org.bukkit.ChatColor;
import org.bukkit.command.PluginCommand;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.List;

/**
 * Thin Ava companion — read-only / soft status signals only.
 * No economy edits, bans, or cross-server credential sharing.
 */
public final class RootAvaCorePlugin extends JavaPlugin {

    private RootRecordYamlConfig yaml;
    private AvaConfig config;

    @Override
    public void onEnable() {
        RootRecordFolders.ensureDir(this);
        yaml = new RootRecordYamlConfig(this, RootRecordFolders.ROOT_AVA_CORE_CONFIG, "root-ava-core.yml");
        yaml.load();
        config = new AvaConfig(yaml.config());

        bindAvaCommand();

        getLogger().info("Ava companion loaded (Root-Ava-Core v" + getDescription().getVersion() + ").");
    }

    public void reloadAll() {
        yaml.load();
        config = new AvaConfig(yaml.config());
        getLogger().info("Root-Ava-Core reloaded.");
    }

    public AvaConfig config() {
        return config;
    }

    private void bindAvaCommand() {
        PluginCommand cmd = getCommand("ava");
        if (cmd == null) {
            cmd = PluginCommandRegistrar.register(
                    this,
                    "ava",
                    "Show Ava companion status",
                    "/ava [reload]",
                    List.of());
        }
        if (cmd == null) {
            getLogger().severe("Could not bind /ava — command missing from plugin.yml and CommandMap fallback failed.");
            return;
        }
        AvaCommand handler = new AvaCommand(this);
        cmd.setExecutor(handler);
        cmd.setTabCompleter(handler);
    }

    @SuppressWarnings("deprecation")
    public String colorize(String input) {
        return ChatColor.translateAlternateColorCodes('&', input == null ? "" : input);
    }
}

